// Test stub for @tapestry/engine.
// Provides only the data.loadYaml binding needed by balance-table.js.
// Resolves pack-relative paths from the oracle pack root.
import { readFileSync } from "node:fs";
import { createRequire } from "node:module";
import { fileURLToPath, URL } from "node:url";

// oracle pack root: this file is at node_modules/@tapestry/engine/index.js
// Relative to the file URL, ../../../ steps: engine -> @tapestry -> node_modules -> oracle/
const packRoot = new URL("../../../", import.meta.url);

// js-yaml is in the monorepo root node_modules
// From oracle/: ../../.. = packages/, ../../ = tapestry-packs/ ... need 6 total from engine/
// engine/ -> @tapestry/ -> node_modules/ -> oracle/ -> @tapestry/ -> packages/ -> tapestry-packs/
const monoRoot = new URL("../../../../../../", import.meta.url);
const require = createRequire(new URL("node_modules/js-yaml/index.js", monoRoot));
const yaml = require(fileURLToPath(new URL("node_modules/js-yaml/index.js", monoRoot)));

export const data = {
    loadYaml(relativePath) {
        const full = new URL(relativePath, packRoot);
        const src = readFileSync(fileURLToPath(full), "utf8");
        return yaml.load(src);
    }
};

// Stub out everything else balance-table does not use.
export const world = {};
export const commands = {};
export const mobs = {};
export const authoring = {};
export const events = {};
export const oracle = {};
